import React from 'react';
import './Ended.css'; // Vytvořte tento soubor pro stylování komponenty

const Ended = ({ score, houseLength }) => {
  return (
    <div className="ended">
      <h2>Game Over!</h2>
      <div className="scoreboard">
        <h3>Final Scores:</h3>
        <ul>
          {score.map((playerScore, index) => (
            <li key={index}>
              Player {playerScore.playerId}: {playerScore.value} {houseLength}
            </li>
          ))}
        </ul>
      </div>
      <div className="house-length">
        <h3>House Length:</h3>
        <p>{houseLength} tiles</p>
      </div>
    </div>
  );
};

export default Ended;
